/**
 * Example usage of DebouncedSave with UserDataService
 * This demonstrates how to integrate the debounced save utility
 * with the existing data service for auto-save functionality.
 */

import DebouncedSave from './DebouncedSave';
import UserDataService from '../services/data/UserDataService';

/**
 * Example implementation showing how to use DebouncedSave
 * in a React Native screen for auto-saving form data
 */
class AutoSaveExample {
  constructor(userId) {
    this.userId = userId;

    // Create debounced save functions for different data types
    this.savePassport = DebouncedSave.debouncedSave(
      `passport_${  userId}`,
      (passportData) => UserDataService.savePassport(passportData, userId),
      300 // 300ms delay
    );

    this.savePersonalInfo = DebouncedSave.debouncedSave(
      `personalInfo_${  userId}`,
      (personalData) => UserDataService.upsertPersonalInfo(userId, personalData),
      300
    );

    this.saveTravelInfo = DebouncedSave.debouncedSave(
      `travelInfo_${  userId}`,
      (travelData) => UserDataService.saveTravelInfo(travelData, userId),
      300
    );
  }

  // Example: Handle passport field changes with auto-save
  handlePassportFieldChange(fieldName, value) {
    const passportData = {
      [fieldName]: value
    };

    // This will debounce the save operation
    this.savePassport(passportData);

    // Get current save state for UI feedback
    const saveState = DebouncedSave.getSaveState(`passport_${  this.userId}`);
    console.log('Save state:', saveState); // 'pending', 'saving', 'saved', 'error', or null
  }

  // Example: Handle personal info field changes
  handlePersonalInfoFieldChange(fieldName, value) {
    const personalData = {
      [fieldName]: value
    };

    this.savePersonalInfo(personalData);
  }

  // Example: Flush all pending saves before navigation
  async handleNavigation() {
    try {
      // Flush all pending saves before navigating
      await DebouncedSave.flushPendingSave();
      console.log('All data saved successfully');

      // Now safe to navigate
      // navigation.navigate('NextScreen');
    } catch (error) {
      console.error('Failed to save data before navigation:', error);
      // Handle error - maybe show alert or block navigation
    }
  }

  // Example: Check if there are unsaved changes
  hasUnsavedChanges() {
    return DebouncedSave.hasPendingSaves();
  }

  // Example: Get save state for UI indicators
  getSaveStateForField(fieldType) {
    const key = `${fieldType  }_${  this.userId}`;
    return DebouncedSave.getSaveState(key);
  }

  // Cleanup when component unmounts
  cleanup() {
    DebouncedSave.clear();
  }
}

export default AutoSaveExample;

/**
 * HelperModal Component
 *
 * Modal component for TDAC WebView copy helper
 * Displays form fields organized by section with copy/autofill functionality
 */

import React from 'react';
import PropTypes from 'prop-types';
import { View, Text, Modal, ScrollView, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import styles from '../../screens/thailand/TDACWebViewScreen.styles';
import { useTranslation } from '../../i18n/LocaleContext';

const HelperModal = ({ visible, onClose, formFields, renderCopyField }) => {
  const { t } = useTranslation();

  return (
    <Modal
      visible={visible}
      animationType="slide"
      onRequestClose={onClose}
    >
      <SafeAreaView style={styles.modalContainer}>
        {/* Modal Header */}
        <View style={styles.modalHeader}>
          <Text style={styles.modalTitle}>{t('thailand.tdacWebView.helperModal.title')}</Text>
          <TouchableOpacity
            onPress={onClose}
            style={styles.closeButton}
          >
            <Text style={styles.closeButtonText}>{t('thailand.tdacWebView.helperModal.close')}</Text>
          </TouchableOpacity>
        </View>

        {/* Copy Helper Content */}
        <ScrollView style={styles.modalContent}>
          {/* Instructions */}
          <View style={styles.instructionBanner}>
            <Text style={styles.instructionIcon}>💡</Text>
            <Text style={styles.instructionText}>
              {t('thailand.tdacWebView.helperModal.instruction')}
            </Text>
          </View>

          {/* Step 1: Personal Information */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.stepBadge}>1</Text>
              <Text style={styles.sectionTitle}>Personal Information</Text>
            </View>
            {formFields
              .filter((f) => f.section === 'personal')
              .map((item) => renderCopyField(item))}
          </View>

          {/* Step 2: Trip Information */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.stepBadge}>2</Text>
              <Text style={styles.sectionTitle}>Trip & Accommodation</Text>
            </View>
            {formFields
              .filter((f) => f.section === 'trip')
              .map((item) => renderCopyField(item))}
          </View>

          {/* Step 3: Accommodation */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.stepBadge}>3</Text>
              <Text style={styles.sectionTitle}>Accommodation</Text>
            </View>
            {formFields
              .filter((f) => f.section === 'accommodation')
              .map((item) => renderCopyField(item))}
          </View>

          {/* Health Declaration Note */}
          <View style={styles.noteCard}>
            <Text style={styles.noteIcon}>⚠️</Text>
            <View style={styles.noteContent}>
              <Text style={styles.noteTitle}>{t('thailand.tdacWebView.helperModal.healthDeclaration.title')}</Text>
              <Text style={styles.noteText}>
                {t('thailand.tdacWebView.helperModal.healthDeclaration.note')}
              </Text>
            </View>
          </View>

          {/* Final Tips */}
          <View style={styles.tipsCard}>
            <Text style={styles.tipsTitle}>{t('thailand.tdacWebView.helperModal.tips.title')}</Text>
            <Text style={styles.tipsText}>
              {t('thailand.tdacWebView.helperModal.tips.items')}
            </Text>
          </View>

          <View style={styles.bottomPadding} />
        </ScrollView>
      </SafeAreaView>
    </Modal>
  );
};

HelperModal.propTypes = {
  visible: PropTypes.bool.isRequired,
  onClose: PropTypes.func.isRequired,
  formFields: PropTypes.arrayOf(PropTypes.shape({
    section: PropTypes.string.isRequired,
    label: PropTypes.string.isRequired,
    labelCn: PropTypes.string,
    value: PropTypes.any,
    field: PropTypes.string.isRequired,
    searchTerms: PropTypes.arrayOf(PropTypes.string),
  })).isRequired,
  renderCopyField: PropTypes.func.isRequired,
};

export default HelperModal;

/**
 * NameParser Utility
 *
 * Utility for parsing passport names into surname, middle name, and given name components.
 * Supports both comma-separated and space-separated name formats.
 */

/**
 * Parses a full name string into surname, middle name, and given name components.
 *
 * Supports two formats:
 * 1. Comma-separated: "Surname, Middle, Given" or "Surname, Given"
 * 2. Space-separated: "Surname Middle Given" or "Surname Given"
 *
 * @param {string} fullName - The full name to parse
 * @returns {{surname: string, middleName: string, givenName: string}} Parsed name components
 *
 * @example
 * parsePassportName("Smith, John, Robert")
 * // Returns: { surname: "Smith", middleName: "John", givenName: "Robert" }
 *
 * @example
 * parsePassportName("Smith, John")
 * // Returns: { surname: "Smith", middleName: "", givenName: "John" }
 *
 * @example
 * parsePassportName("John Robert Smith")
 * // Returns: { surname: "John", middleName: "Robert", givenName: "Smith" }
 */
export const parsePassportName = (fullName) => {
  const result = {
    surname: '',
    middleName: '',
    givenName: '',
  };

  if (!fullName || typeof fullName !== 'string') {
    return result;
  }

  const nameToParse = fullName.trim();

  if (!nameToParse) {
    return result;
  }

  // Handle comma-separated format (e.g., "Surname, Middle, Given")
  if (nameToParse.includes(',')) {
    const parts = nameToParse.split(',').map(part => part.trim());

    if (parts.length === 3) {
      result.surname = parts[0];
      result.middleName = parts[1];
      result.givenName = parts[2];
    } else if (parts.length === 2) {
      result.surname = parts[0];
      result.middleName = '';
      result.givenName = parts[1];
    } else if (parts.length === 1) {
      result.surname = parts[0];
      result.middleName = '';
      result.givenName = '';
    }
  } else {
    // Handle space-separated format (e.g., "Surname Middle Given")
    const spaceParts = nameToParse.split(/\s+/);

    if (spaceParts.length >= 3) {
      result.surname = spaceParts[0];
      result.middleName = spaceParts[1];
      result.givenName = spaceParts.slice(2).join(' ');
    } else if (spaceParts.length === 2) {
      result.surname = spaceParts[0];
      result.middleName = '';
      result.givenName = spaceParts[1];
    } else if (spaceParts.length === 1) {
      result.surname = spaceParts[0];
      result.middleName = '';
      result.givenName = '';
    }
  }

  return result;
};

/**
 * Formats name components back into a full name string.
 *
 * @param {string} surname - The surname
 * @param {string} middleName - The middle name (optional)
 * @param {string} givenName - The given name
 * @param {boolean} useCommaFormat - If true, uses comma-separated format; otherwise space-separated
 * @returns {string} The formatted full name
 *
 * @example
 * formatFullName("Smith", "John", "Robert", true)
 * // Returns: "Smith, John, Robert"
 *
 * @example
 * formatFullName("Smith", "", "John", false)
 * // Returns: "Smith John"
 */
export const formatFullName = (surname, middleName, givenName, useCommaFormat = false) => {
  const parts = [surname, middleName, givenName].filter(part => part && part.trim());

  if (useCommaFormat) {
    return parts.join(', ');
  }

  return parts.join(' ');
};

export default {
  parsePassportName,
  formatFullName,
};

