        getSubDistricts: () => []
      };

    default:
      return {
        provinces: [],
        getDistricts: () => [],
        getSubDistricts: () => []
      };
  }
};

export default getLocationLoaders;

/**
 * Arrival Window Calculator Utility for Hong Kong
 * Hong Kong doesn't have a specific submission window like Thailand's 72-hour rule
 * Arrival cards can be submitted anytime before arrival
 *
 * Simplified version for Hong Kong Entry Flow
 */

class ArrivalWindowCalculator {
  /**
   * Calculate submission window for Hong Kong arrival
   * Hong Kong doesn't have time restrictions, so always returns canSubmit: true
   * @param {string|Date} arrivalDate - Arrival date (YYYY-MM-DD or Date object)
   * @returns {Object} - Arrival window information
   */
  static calculateWindow(arrivalDate) {
    if (!arrivalDate) {
      return {
        isWithin72Hours: false,
        hoursRemaining: null,
        canSubmit: false,
        arrivalDate: null,
        submissionWindowStart: null,
        daysRemaining: null,
        hoursUntilWindow: null
      };
    }

    const arrival = new Date(arrivalDate);
    const now = new Date();

    // Calculate time until arrival
    const msUntilArrival = arrival.getTime() - now.getTime();
    const hoursUntilArrival = msUntilArrival / (1000 * 60 * 60);
    const daysUntilArrival = hoursUntilArrival / 24;

    // Hong Kong: No specific window, can submit anytime before arrival
    const canSubmit = hoursUntilArrival > 0;

    return {
      isWithin72Hours: true, // Always true for Hong Kong (no restriction)
      hoursRemaining: Math.max(0, hoursUntilArrival),
      canSubmit,
      arrivalDate: arrival,
      submissionWindowStart: null, // No window start for Hong Kong
      daysRemaining: Math.max(0, Math.ceil(daysUntilArrival)),
      hoursUntilWindow: 0, // Window is always open
      status: hoursUntilArrival <= 0 ? 'past' : 'open'
    };
  }

  /**
   * Get submission window details for display
   * @param {string|Date} arrivalDate - Arrival date
   * @returns {Object} - Window details with user-friendly messages
   */
  static getSubmissionWindow(arrivalDate) {
    const window = this.calculateWindow(arrivalDate);

    return {
      ...window,
      message: window.canSubmit
        ? '可以提交入境卡 / Ready to submit'
        : '抵达日期已过 / Arrival date has passed',
      windowStatus: window.canSubmit ? 'open' : 'closed'
    };
  }

  /**
   * Check if arrival date is in the past
   * @param {string|Date} arrivalDate - Arrival date
   * @returns {boolean} - True if date is in the past
   */
  static isArrivalPast(arrivalDate) {
    if (!arrivalDate) {
return false;
}
    const arrival = new Date(arrivalDate);
    const now = new Date();
    return arrival.getTime() < now.getTime();
  }

  /**
   * Get days until arrival
   * @param {string|Date} arrivalDate - Arrival date
   * @returns {number} - Days until arrival (0 if past)
   */
  static getDaysUntilArrival(arrivalDate) {
    const window = this.calculateWindow(arrivalDate);
    return window.daysRemaining || 0;
  }
}

export default ArrivalWindowCalculator;

/**
 * Field Value Helpers
 *
 * Utilities for checking if field values are valid and should be saved.
 * Handles different data types correctly (booleans, numbers, strings, objects).
 */

/**
 * Check if a value is valid and should be saved
 *
 * @param {any} value - The value to check
 * @returns {boolean} True if the value is valid and non-empty
 *
 * Rules:
 * - null/undefined: invalid (false)
 * - Boolean: always valid (true/false are both meaningful values)
 * - Number: always valid (0, 1, -1 are all meaningful)
 * - String: valid if non-empty after trimming
 * - Array: valid if has at least one element
 * - Object: valid if has at least one property
 */
export const hasValidValue = (value) => {
  // null or undefined are not valid values
  if (value === null || value === undefined) {
    return false;
  }

  // Booleans are always valid (both true and false are meaningful)
  if (typeof value === 'boolean') {
    return true;
  }

  // Numbers are always valid (including 0)
  if (typeof value === 'number') {
    return !isNaN(value);
  }

  // Strings must be non-empty after trimming
  if (typeof value === 'string') {
    return value.trim() !== '';
  }

  // Arrays must have at least one element
  if (Array.isArray(value)) {
    return value.length > 0;
  }

  // Objects must have at least one property
  if (typeof value === 'object') {
    return Object.keys(value).length > 0;
  }

  // Default: check truthiness
  return Boolean(value);
};

/**
 * Check if two values are effectively different
 *
 * @param {any} value1 - First value
 * @param {any} value2 - Second value
 * @returns {boolean} True if values are different
 *
 * Handles:
 * - Type coercion (e.g., '1' vs 1)
 * - Empty string vs null/undefined
 * - Arrays and objects (shallow comparison)
 */
export const hasValueChanged = (value1, value2) => {
  // Same reference or strict equality
  if (value1 === value2) {
    return false;
  }

  // Both are "empty" (null, undefined, or empty string)
  const isEmpty1 = value1 === null || value1 === undefined || value1 === '';
  const isEmpty2 = value2 === null || value2 === undefined || value2 === '';
  if (isEmpty1 && isEmpty2) {
    return false;
  }

  // Different types
  if (typeof value1 !== typeof value2) {
    return true;
  }

  // Arrays - shallow comparison
  if (Array.isArray(value1) && Array.isArray(value2)) {
    if (value1.length !== value2.length) {
return true;
}
    return value1.some((item, index) => item !== value2[index]);
  }

  // Objects - shallow comparison
  if (typeof value1 === 'object' && value1 !== null && value2 !== null) {
    const keys1 = Object.keys(value1);
    const keys2 = Object.keys(value2);
    if (keys1.length !== keys2.length) {
return true;
}
    return keys1.some(key => value1[key] !== value2[key]);
  }

  // Default: values are different
  return true;
};

/**
 * Normalize a field value for consistent comparison and storage
 *
 * @param {any} value - The value to normalize
 * @returns {any} Normalized value
 *
 * Rules:
 * - null/undefined → null
 * - Empty string → null
 * - Non-empty string → trimmed string
 * - Boolean/Number → unchanged
 * - Array/Object → unchanged
 */
export const normalizeFieldValue = (value) => {
  // null or undefined → null
  if (value === null || value === undefined) {
    return null;
  }

  // Empty string → null
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }

  // All other types unchanged
  return value;
};

export default {
  hasValidValue,
  hasValueChanged,
  normalizeFieldValue,
};

/**
 * Date utility functions to handle timezone-safe date parsing and formatting.
 *
 * IMPORTANT: Date strings in YYYY-MM-DD format should always be interpreted as LOCAL dates,
 * not UTC. This prevents timezone conversion bugs where dates change when parsed.
 *
 * For example:
 * - BAD: new Date("2025-10-31") → Interprets as UTC midnight, displays as Oct 30 in UTC+7/+8
 * - GOOD: parseLocalDate("2025-10-31") → Interprets as Oct 31 at midnight local time
 */

/**
 * Parses a date string in YYYY-MM-DD format as a local date.
 * This prevents timezone conversion issues where dates change due to UTC interpretation.
 *
 * @param {string|Date|null|undefined} dateValue - Date string in YYYY-MM-DD format, Date object, or null/undefined
 * @returns {Date|null} Date object representing the local date, or null if invalid
 *
 * @example
 * parseLocalDate("2025-10-31") // Returns Oct 31, 2025 at 00:00:00 local time
 * parseLocalDate(new Date()) // Returns the same Date object
 * parseLocalDate(null) // Returns null
 */
export function parseLocalDate(dateValue) {
  if (!dateValue) {
    return null;
  }

  // If already a Date object, return as-is
  if (dateValue instanceof Date) {
    return dateValue;
  }

  // If it's a string, parse it as local date
  if (typeof dateValue === 'string') {
    // Handle YYYY-MM-DD format
    const match = dateValue.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (match) {
      const [, year, month, day] = match;
      // Create date in local timezone (month is 0-indexed)
      return new Date(parseInt(year, 10), parseInt(month, 10) - 1, parseInt(day, 10));
    }
  }

  // Fallback: try to create Date object (may have timezone issues)
  try {
    const date = new Date(dateValue);
    return isNaN(date.getTime()) ? null : date;
  } catch (e) {
    return null;
  }
}

/**
 * Formats a Date object as YYYY-MM-DD string using LOCAL timezone.
 * This ensures the date string represents the same calendar date as displayed locally.
 *
 * @param {Date|string|null|undefined} dateValue - Date object, date string, or null/undefined
 * @returns {string|null} Date string in YYYY-MM-DD format, or null if invalid
 *
 * @example
 * formatLocalDate(new Date(2025, 9, 31)) // Returns "2025-10-31"
 * formatLocalDate("2025-10-31") // Returns "2025-10-31" (passes through if already valid)
 * formatLocalDate(null) // Returns null
 */
export function formatLocalDate(dateValue) {
  if (!dateValue) {
    return null;
  }

  // If it's already a valid YYYY-MM-DD string, return as-is
  if (typeof dateValue === 'string') {
    const match = dateValue.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (match) {
      return dateValue;
    }
  }

  // Convert to Date if needed
  let date = dateValue;
  if (!(date instanceof Date)) {
    date = parseLocalDate(dateValue);
    if (!date) {
      return null;
    }
  }

  // Format using local timezone
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Checks if a value is a valid date string in YYYY-MM-DD format.
 *
 * @param {any} value - Value to check
 * @returns {boolean} True if value is a valid YYYY-MM-DD date string
 */
export function isValidDateString(value) {
  if (typeof value !== 'string') {
    return false;
  }

  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    return false;
  }

  // Verify it's a valid calendar date
  const date = parseLocalDate(value);
  return date !== null && !isNaN(date.getTime());
}

/**
 * Formats a date for display in Chinese format (年月日).
 *
 * @param {Date|string|null|undefined} dateValue - Date to format
 * @returns {string} Formatted date string or empty string if invalid
 *
 * @example
 * formatChineseDate("2025-10-31") // Returns "2025年10月31日"
 */
export function formatChineseDate(dateValue) {
  if (!dateValue) {
    return '';
  }

  const date = parseLocalDate(dateValue);
  if (!date) {
    return '';
  }

  try {
    return `${date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).replace(/\//g, '年').replace(/年(\d+)年/, '年$1月')  }日`;
  } catch (e) {
    // Fallback to manual formatting
    const year = date.getFullYear();
    const month = date.getMonth() + 1;
    const day = date.getDate();
    return `${year}年${month}月${day}日`;
  }
}

