  country_code: string;
  visa_required?: number;
  max_stay_days?: number;
  notes?: string;
  created_at?: string;
  [key: string]: unknown;
}
```

Differences: local has `max_stay_days?: number | null` vs `number`, `notes?: string | null` vs `string`.

